const markMigrationApplied = `-- name: MarkMigrationApplied :exec
UPDATE migrations
SET status     = 'applied',
    version    = $1,
    applied_by = $2,
    applied_at = now(),
    updated_at = now()
WHERE id = $3
`

type MarkMigrationAppliedParams struct {
	Version   pgtype.Int4
	AppliedBy pgtype.Int8
	ID        int64
}

func (q *Queries) MarkMigrationApplied(ctx context.Context, arg MarkMigrationAppliedParams) error {
	_, err := q.db.Exec(ctx, markMigrationApplied, arg.Version, arg.AppliedBy, arg.ID)
	return err
}

const markMigrationRolledBack = `-- name: MarkMigrationRolledBack :exec
UPDATE migrations
SET status     = 'rolled_back',
    version    = NULL,
    updated_at = now()
WHERE id = $1
`

func (q *Queries) MarkMigrationRolledBack(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, markMigrationRolledBack, id)
	return err
}

const migrationHead = `-- name: MigrationHead :one
SELECT COALESCE(MAX(version), 0)::int AS head
FROM migrations
WHERE database_id = $1 AND status = 'applied'
`

func (q *Queries) MigrationHead(ctx context.Context, databaseID int64) (int32, error) {
	row := q.db.QueryRow(ctx, migrationHead, databaseID)
	var head int32
	err := row.Scan(&head)
	return head, err
}

